    private static readonly Dictionary<string, string> Upper = Texts.Keys.Where(k => k.Any(char.IsLetter) && k == k.ToUpperInvariant()).ToDictionary(k => k, k => k);

    private static int Index => Array.IndexOf(Codes, L.Code);

    public static string? Lookup(string source)
    {
        int index = Index;
        if (index < 0) return null;
        if (Texts.TryGetValue(source, out var row)) return row[index];
        var key = Texts.Keys.FirstOrDefault(k => string.Equals(k, source, StringComparison.OrdinalIgnoreCase));
        if (key == null) return null;
        var text = Texts[key][index];
        return source.Any(char.IsLetter) && source == source.ToUpperInvariant() ? text.ToUpper(L.Culture) : text;
    }

    public static string T(string source) => Lookup(source) ?? EnglishText.Fix(source);

    public static string F(string source, params object?[] args) => string.Format(L.Culture, T(source), args);

    private const string EnglishNote = "How it works: for each chest you opened since the weekly reset, a prize has a 1-in-N chance. Chests opened inside a Treasure Hour use the boosted rate. The big percentage and the solid bars are what you have really earned this week, so they stay empty until you open chests. The dashed outline (on the selected or hovered row) and the planner show what your chosen number of chests would be worth, with and without the Treasure Hour. Chests from a match still in progress count once it ends. Treasure Hour times come from your 2xflaw-odds.json file. Confirmed boosts are applied using your local schedule. Unconfirmed windows count as normal odds until their boosts are confirmed. Pirate Shop Access uses your all-time personal history (as configured); the other prizes are weekly. Chests without exact opening times use the base odds. Except for Gizmos, you cannot get the same prize twice.";
    private static readonly string[] Notes = { "Cómo funciona: por cada cofre que abriste desde el reinicio semanal, un premio tiene una probabilidad de 1 entre N. Los cofres abiertos durante una Hora del Tesoro usan la tasa reforzada. El porcentaje grande y las barras sólidas muestran lo que realmente has conseguido esta semana, así que permanecen vacíos hasta que abras cofres. El contorno discontinuo (fila seleccionada o bajo el cursor) y el planificador muestran lo que valdría la cantidad de cofres que elijas, con y sin la Hora del Tesoro. Los cofres de una partida en curso cuentan cuando termina. Los horarios de la Hora del Tesoro proceden de tu archivo 2xflaw-odds.json. Los refuerzos confirmados se aplican según tu horario local. Las franjas sin confirmar cuentan con probabilidad normal hasta que se confirmen sus refuerzos. El acceso a la tienda pirata usa todo el historial personal configurado; los demás premios siguen siendo semanales. Los recuentos sin hora exacta de apertura usan la probabilidad base. Salvo los artilugios, no puedes conseguir el mismo premio dos veces.", "Como funciona: para cada baú aberto desde o reinício semanal, um prêmio tem uma chance de 1 em N. Baús abertos durante uma Hora do Tesouro usam a taxa com bônus. A porcentagem grande e as barras sólidas mostram o que você realmente conseguiu nesta semana, então ficam vazias até você abrir baús. O contorno tracejado (linha selecionada ou sob o cursor) e o planejador mostram quanto valeria a quantidade de baús escolhida, com e sem a Hora do Tesouro. Baús de uma partida em andamento contam quando ela termina. Os horários da Hora do Tesouro vêm do seu arquivo 2xflaw-odds.json. Bônus confirmados são aplicados conforme seu horário local. Janelas não confirmadas contam com chance normal até que seus bônus sejam confirmados. O acesso à loja pirata usa todo o histórico pessoal configurado; os outros prêmios continuam semanais. Contagens sem horário exato de abertura usam a chance base. Exceto pelos dispositivos, não é possível obter o mesmo prêmio duas vezes.", "Как это работает: за каждый сундук, открытый после недельного сброса, награда выпадает с шансом 1 из N. Для сундуков, открытых во время Часа сокровищ, используется повышенный шанс. Крупный процент и сплошные полосы показывают то, что вы действительно набрали за неделю, поэтому они пусты, пока вы не откроете сундуки. Пунктирный контур (выбранная или наведённая строка) и планировщик показывают, сколько дало бы выбранное количество сундуков — с Часом сокровищ и без него. Сундуки из незавершённого матча засчитываются после его окончания. Время Часов сокровищ берётся из файла 2xflaw-odds.json. Подтверждённые бонусы применяются по вашему местному расписанию. Неподтверждённые окна считаются с обычным шансом, пока бонусы не подтверждены. Для доступа в пиратский магазин используется вся настроенная личная история; остальные награды по-прежнему считаются за неделю. Количества без точного времени открытия используют базовый шанс. Кроме гизмо, одну и ту же награду нельзя получить дважды.", "Fonctionnement : pour chaque coffre ouvert depuis la réinitialisation hebdomadaire, une récompense a une chance de 1 sur N. Les coffres ouverts pendant une Heure du trésor utilisent le taux bonifié. Le grand pourcentage et les barres pleines indiquent ce que vous avez réellement obtenu cette semaine ; ils restent donc vides tant que vous n’ouvrez pas de coffres. Le contour en pointillés (ligne sélectionnée ou survolée) et le planificateur montrent ce que vaudrait le nombre de coffres choisi, avec et sans l’Heure du trésor. Les coffres d’une partie en cours comptent une fois celle-ci terminée. Les horaires des Heures du trésor proviennent de votre fichier 2xflaw-odds.json. Les bonus confirmés sont appliqués selon votre horaire local. Les créneaux non confirmés comptent au taux normal jusqu’à la confirmation de leurs bonus. L’accès à la boutique pirate utilise tout l’historique personnel configuré ; les autres récompenses restent hebdomadaires. Les nombres sans heure d’ouverture exacte utilisent le taux de base. Sauf pour les gadgets, vous ne pouvez pas obtenir deux fois la même récompense.", "So funktioniert es: Für jede Truhe, die du seit dem wöchentlichen Reset geöffnet hast, hat eine Belohnung eine Chance von 1 zu N. Truhen, die während einer Schatzstunde geöffnet werden, nutzen die erhöhte Rate. Der große Prozentwert und die durchgehenden Balken zeigen, was du diese Woche tatsächlich erreicht hast, und bleiben daher leer, bis du Truhen öffnest. Der gestrichelte Umriss (ausgewählte oder überfahrene Zeile) und der Planer zeigen, was die gewählte Anzahl Truhen wert wäre – mit und ohne Schatzstunde. Truhen aus einem laufenden Match zählen, sobald es endet. Die Zeiten der Schatzstunden stammen aus deiner Datei 2xflaw-odds.json. Bestätigte Boosts werden nach deinem lokalen Zeitplan angewendet. Unbestätigte Zeitfenster zählen mit normaler Rate, bis ihre Boosts bestätigt sind. Der Zugang zum Piratenshop nutzt den gesamten konfigurierten persönlichen Verlauf; andere Belohnungen bleiben wöchentlich. Anzahlen ohne genaue Öffnungszeit nutzen die Basisrate. Außer Gizmos kannst du dieselbe Belohnung nicht zweimal erhalten.", "Come funziona: per ogni forziere aperto dal reset settimanale, un premio ha una probabilità di 1 su N. I forzieri aperti durante un’Ora del Tesoro usano la probabilità potenziata. La percentuale grande e le barre piene mostrano ciò che hai davvero ottenuto questa settimana, quindi restano vuote finché non apri forzieri. Il contorno tratteggiato (riga selezionata o sotto il cursore) e il pianificatore mostrano quanto varrebbe il numero di forzieri scelto, con e senza l’Ora del Tesoro. I forzieri di una partita in corso contano quando termina. Gli orari dell’Ora del Tesoro provengono dal tuo file 2xflaw-odds.json. I potenziamenti confermati vengono applicati secondo il tuo orario locale. Le fasce non confermate contano con la probabilità normale finché i potenziamenti non sono confermati. L’accesso al negozio pirata usa tutta la cronologia personale configurata; gli altri premi restano settimanali. I conteggi senza orario di apertura esatto usano la probabilità base. Tranne i dispositivi, non puoi ottenere lo stesso premio due volte.", "Jak to działa: za każdą skrzynię otwartą od tygodniowego resetu nagroda ma szansę 1 na N. Skrzynie otwarte podczas Godziny Skarbów korzystają ze zwiększonej szansy. Duży procent i pełne paski pokazują to, co naprawdę zdobyłeś w tym tygodniu, więc pozostają puste, dopóki nie otworzysz skrzyń. Przerywany kontur (zaznaczony lub wskazany wiersz) i planer pokazują, ile byłaby warta wybrana liczba skrzyń – z Godziną Skarbów i bez niej. Skrzynie z trwającego meczu liczą się po jego zakończeniu. Godziny Skarbów pochodzą z pliku 2xflaw-odds.json. Potwierdzone bonusy są stosowane według twojego lokalnego harmonogramu. Niepotwierdzone okna liczą się ze zwykłą szansą, dopóki bonusy nie zostaną potwierdzone. Dostęp do sklepu pirackiego korzysta z całej skonfigurowanej historii osobistej; pozostałe nagrody pozostają tygodniowe. Liczby bez dokładnego czasu otwarcia używają podstawowej szansy. Poza gadżetami nie można zdobyć tej samej nagrody dwa razy.", "Nasıl çalışır: Haftalık sıfırlamadan bu yana açtığınız her sandık için bir ödülün 1/N olasılığı vardır. Hazine Saati sırasında açılan sandıklar artırılmış oranı kullanır. Büyük yüzde ve dolu çubuklar bu hafta gerçekten kazandığınızı gösterir; bu yüzden sandık açana kadar boş kalır. Kesikli çerçeve (seçili veya üzerine gelinen satır) ve planlayıcı, seçtiğiniz sandık sayısının Hazine Saati ile ve olmadan ne kadar değerli olacağını gösterir. Devam eden bir maçın sandıkları maç bitince sayılır. Hazine Saati zamanları 2xflaw-odds.json dosyanızdan gelir. Onaylanan bonuslar yerel programınıza göre uygulanır. Onaylanmamış zaman aralıkları, bonusları onaylanana kadar normal oranla sayılır. Korsan dükkânı erişimi yapılandırılmış tüm kişisel geçmişi kullanır; diğer ödüller haftalık kalır. Tam açılış zamanı olmayan sayımlar temel oranı kullanır. Aygıtlar dışında aynı ödülü iki kez alamazsınız.", "仕組み：週次リセット以降に開けた宝箱1個ごとに、各報酬はN分の1の確率で出ます。トレジャーアワー中に開けた宝箱にはブースト後の確率が適用されます。大きなパーセンテージと塗りつぶしのバーは今週実際に得た確率を示すため、宝箱を開けるまでは空のままです。破線の枠（選択中またはカーソルを合わせた行）とプランナーは、選んだ数の宝箱を開けた場合の価値を、トレジャーアワーありとなしで示します。進行中のマッチの宝箱は、マッチ終了後に加算されます。トレジャーアワーの時間は2xflaw-odds.jsonファイルから取得します。確定したブーストはローカルのスケジュールに沿って適用されます。未確定の時間帯は、ブーストが確定するまで通常確率で計算されます。海賊ショップへのアクセスは設定済みの全期間の個人履歴を使い、その他の報酬は引き続き週単位です。正確な開封時刻がない数は基本確率を使います。ギズモを除き、同じ報酬を2回入手することはできません。" };
    private static readonly string[][] Hidden = { new[] { " {0} owned prize hidden: untick it in Weekly rewards to bring it back.", " {0} owned prizes hidden: untick them in Weekly rewards to bring them back." }, new[] { " {0} premio obtenido oculto: desmárcalo en Recompensas semanales para recuperarlo.", " {0} premios obtenidos ocultos: desmárcalos en Recompensas semanales para recuperarlos." }, new[] { " {0} prêmio obtido oculto: desmarque-o em Recompensas semanais para trazê-lo de volta.", " {0} prêmios obtidos ocultos: desmarque-os em Recompensas semanais para trazê-los de volta." }, new[] { " Скрыто полученных наград: {0}. Снимите отметку в окне «Недельные награды», чтобы вернуть их.", " Скрыто полученных наград: {0}. Снимите отметку в окне «Недельные награды», чтобы вернуть их." }, new[] { " {0} récompense obtenue masquée : décochez-la dans Récompenses hebdomadaires pour la réafficher.", " {0} récompenses obtenues masquées : décochez-les dans Récompenses hebdomadaires pour les réafficher." }, new[] { " {0} Belohnung im Besitz ausgeblendet: Entferne das Häkchen unter Wöchentliche Belohnungen, um sie wieder anzuzeigen.", " {0} Belohnungen im Besitz ausgeblendet: Entferne die Häkchen unter Wöchentliche Belohnungen, um sie wieder anzuzeigen." }, new[] { " {0} premio posseduto nascosto: deselezionalo in Premi settimanali per mostrarlo di nuovo.", " {0} premi posseduti nascosti: deselezionali in Premi settimanali per mostrarli di nuovo." }, new[] { " Ukryte posiadane nagrody: {0}. Odznacz je w oknie Nagrody tygodniowe, aby je przywrócić.", " Ukryte posiadane nagrody: {0}. Odznacz je w oknie Nagrody tygodniowe, aby je przywrócić." }, new[] { " Sahip olunan {0} ödül gizlendi: Geri getirmek için Haftalık ödüller bölümünde işaretini kaldırın.", " Sahip olunan {0} ödül gizlendi: Geri getirmek için Haftalık ödüller bölümünde işaretlerini kaldırın." }, new[] { " 所持済みの報酬{0}件を非表示中：再表示するには「毎週の報酬」でチェックを外してください。", " 所持済みの報酬{0}件を非表示中：再表示するには「毎週の報酬」でチェックを外してください。" } };

    // Golden Week (Nov 28 to Dec 5): explains the "any" rows, the pool and the Treasure Hour multiplier during it.
    private static readonly string[] GoldenNotes =
    {
        "Golden Week (28 Nov to 5 Dec): every earlier week's treasure is back. Each item keeps its own odds, except Gold Outfits at 2x (1 in 781,250 each), so each row shows the chance of any item of that kind you still need, for example any of 5 Gold Vehicles is 1 in 1,563. Anything you tick in Weekly rewards leaves the pool. The Golden Week Treasure Hour (each Gold Outfit 1 in 104,167, each vehicle 1 in 781) is shown on top, so it reads 7.5x and 10x.",
        "Semana Dorada (28 nov - 5 dic): vuelve el tesoro de todas las semanas anteriores. Cada objeto mantiene sus probabilidades, salvo los atuendos de oro a x2 (1 de 781.250 cada uno), así que cada fila muestra la probabilidad de cualquier objeto de ese tipo que aún te falte; por ejemplo, cualquiera de los 5 vehículos de oro es 1 de 1.563. Lo que marques en Recompensas semanales sale del grupo. La Hora del Tesoro de la Semana Dorada (cada atuendo 1 de 104.167, cada vehículo 1 de 781) se muestra encima, así que aparece como x7,5 y x10.",
        "Semana Dourada (28 nov - 5 dez): o tesouro de todas as semanas anteriores volta. Cada item mantém sua chance, exceto os trajes de ouro em 2x (1 em 781.250 cada), então cada linha mostra a chance de qualquer item desse tipo que ainda falta; por exemplo, qualquer um dos 5 veículos de ouro é 1 em 1.563. O que você marcar em Recompensas semanais sai do conjunto. A Hora do Tesouro da Semana Dourada (cada traje 1 em 104.167, cada veículo 1 em 781) aparece por cima, então mostra 7,5x e 10x.",
        "Золотая неделя (28 ноя - 5 дек): возвращаются сокровища всех прошлых недель. У каждого предмета свои шансы, кроме золотых костюмов x2 (1 из 781 250 каждый), поэтому каждая строка показывает шанс получить любой ещё не найденный предмет этого типа; например, любой из 5 золотых транспортов - 1 из 1 563. Отмеченное в еженедельных наградах убирается из пула. Час сокровищ Золотой недели (каждый костюм 1 из 104 167, каждый транспорт 1 из 781) показан поверх, поэтому видно x7,5 и x10.",
        "Semaine dorée (28 nov - 5 déc) : le trésor de toutes les semaines précédentes revient. Chaque objet garde ses chances, sauf les tenues en or à x2 (1 sur 781 250 chacune), donc chaque ligne montre la chance d'obtenir n'importe quel objet de ce type qu'il vous manque ; par exemple, n'importe lequel des 5 véhicules en or est à 1 sur 1 563. Ce que vous cochez dans Récompenses hebdomadaires quitte le lot. L'Heure du trésor de la Semaine dorée (chaque tenue 1 sur 104 167, chaque véhicule 1 sur 781) s'affiche par-dessus, donc x7,5 et x10.",
        "Goldene Woche (28. Nov - 5. Dez): Der Schatz aller früheren Wochen ist zurück. Jeder Gegenstand behält seine Chance, nur Gold-Outfits sind 2x (je 1 zu 781.250). Jede Zeile zeigt deshalb die Chance auf einen beliebigen Gegenstand dieser Art, der dir noch fehlt; zum Beispiel ist eins der 5 Gold-Fahrzeuge 1 zu 1.563. Was du in Wöchentliche Belohnungen abhakst, verlässt den Pool. Die Schatzstunde der Goldenen Woche (jedes Outfit 1 zu 104.167, jedes Fahrzeug 1 zu 781) kommt obendrauf und zeigt daher 7,5x und 10x.",
        "Settimana d'oro (28 nov - 5 dic): torna il tesoro di tutte le settimane precedenti. Ogni oggetto mantiene le sue probabilità, tranne i costumi d'oro a 2x (1 su 781.250 ciascuno), quindi ogni riga mostra la probabilità di un qualsiasi oggetto di quel tipo che ti manca; per esempio, uno qualsiasi dei 5 veicoli d'oro è 1 su 1.563. Ciò che spunti in Ricompense settimanali esce dal gruppo. L'Ora del tesoro della Settimana d'oro (ogni costume 1 su 104.167, ogni veicolo 1 su 781) si somma sopra, quindi indica 7,5x e 10x.",
        "Złoty tydzień (28 lis - 5 gru): wraca skarb ze wszystkich wcześniejszych tygodni. Każdy przedmiot ma własne szanse, poza złotymi strojami 2x (każdy 1 na 781 250), więc każdy wiersz pokazuje szansę na dowolny przedmiot tego rodzaju, którego jeszcze nie masz; np. dowolny z 5 złotych pojazdów to 1 na 1563. To, co zaznaczysz w Cotygodniowych nagrodach, znika z puli. Godzina skarbów Złotego tygodnia (każdy strój 1 na 104 167, każdy pojazd 1 na 781) jest liczona ponad tym, więc widać 7,5x i 10x.",
        "Altın Hafta (28 Kas - 5 Ara): önceki tüm haftaların hazineleri geri döner. Her eşya kendi şansını korur, yalnızca Altın Kıyafetler 2x'tir (her biri 781.250'de 1); bu yüzden her satır o türden henüz bulmadığın herhangi bir eşyanın şansını gösterir, örneğin 5 Altın Araçtan herhangi biri 1.563'te 1'dir. Haftalık ödüllerde işaretlediğin eşyalar havuzdan çıkar. Altın Hafta Hazine Saati (her kıyafet 104.167'de 1, her araç 781'de 1) bunun üzerine gösterilir, bu yüzden 7,5x ve 10x yazar.",
        "ゴールデンウィーク (11/28 - 12/5): これまでの全週の宝が復活します。各アイテムの確率はそのままで、ゴールドスキンのみ2倍 (各781,250分の1) です。そのため各行には、その種類でまだ持っていないいずれかのアイテムの確率を表示します (例: 5台のゴールド乗り物のいずれかは1,563分の1)。週間報酬でチェックしたアイテムはプールから外れます。ゴールデンウィークのトレジャーアワー (各スキン104,167分の1、各乗り物781分の1) はその上乗せとして7.5倍と10倍で表示されます。",
    };

    public static string Note(int hidden)
    {
        int index = Index;
        var text = index < 0 ? EnglishNote : Notes[index];
        if (DateTime.UtcNow < TreasureHours.GoldenWeekEndUtc) text += " " + GoldenNotes[index + 1];
        if (hidden <= 0) return text;
        var forms = Hidden[index + 1];
        return text + string.Format(L.Culture, hidden == 1 ? forms[0] : forms[1], hidden);
    }
}
